package com.irwi.fincapp.ui;
import android.app.*;import android.os.*;import android.widget.*;import com.irwi.fincapp.network.*;import com.irwi.fincapp.session.SessionManager;import java.util.*;import retrofit2.*;
public class AuraActivity extends Activity{TextView response; public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=BaseUi.root(this);l.addView(BaseUi.title(this,"AURA Assistant"));l.addView(BaseUi.text(this,"Ask farm questions. If backend is unavailable, the app stays usable offline.",18));EditText q=BaseUi.input(this,"Ask AURA...");Button ask=BaseUi.btn(this,"Ask");response=BaseUi.text(this,"",18);l.addView(q);l.addView(ask);l.addView(response);ask.setOnClickListener(v->{String text=q.getText().toString();if(text.trim().isEmpty())return;response.setText("Thinking...");Map<String,String> body=new HashMap<>();body.put("text",text);body.put("farmId",new SessionManager(this).farmId());ApiClient.service(new SessionManager(this).baseUrl()).askAura(body).enqueue(new Callback<Map<String,Object>>(){public void onResponse(Call<Map<String,Object>> c,Response<Map<String,Object>> r){response.setText(r.isSuccessful()?String.valueOf(r.body()):"Backend response: "+r.code());}public void onFailure(Call<Map<String,Object>> c,Throwable t){response.setText("Offline or backend unavailable. Try again when connected.");}});});}}
